def check(value, message):
    if not value:
        raise ValueError(message)


def verified_file(path, expected):
    path = Path(path).resolve(strict=True)
    check(expected and identity.sha(path) == expected, 'Changed identity file: ' + str(path))
    return path


def descriptor_inputs(descriptor):
    result = {}
    for key, value in descriptor.items():
        if not key.endswith('File') or not isinstance(value, str):
            continue
        digest = descriptor.get(key + 'Sha256', descriptor.get(key[:-4] + 'Sha256'))
        check(digest is not None, 'Descriptor file is not hash-pinned: ' + key)
        result[key] = verified_file(value, digest)
    return result


def validated_selection(path):
    selection = json.loads(Path(path).read_text())
    check(selection['format'] == 1 and set(selection['fixtureMasks']) == set(FIXTURE_ORDER),
          'Selection must cover precisely the two frozen fixtures')
    check(selection['unrefusedDenseAdmissionAt512MiB'] is True
          and selection['denseResolverCountsEqualPerFixture'] is True,
          '512 MiB diagnostics must establish unrefused admissions and unchanged resolver counts')
    for fixture, names in selection['fixtureMasks'].items():
        check(isinstance(names, list) and names and len(names) == len(set(names))
              and all(isinstance(n, str) and n in FIXTURES[fixture]['projectedNames'] for n in names),
              'Invalid or empty fixture-specific target mask: ' + fixture)
    check(selection['fixtureMasks']['shared-tail'] == ['l0', 'l1'], 'Shared-tail hypothesis changed')
    evidence = selection['diagnosticEvidenceFiles']
    check(evidence and len({e['path'] for e in evidence}) == len(evidence), 'Missing or duplicate diagnostic evidence')
    for entry in evidence:
        verified_file(entry['path'], entry['sha256'])
    return selection


def validate_runtime(path):
    descriptor = json.loads(Path(path).read_text())
    inputs = descriptor_inputs(descriptor)
    required = {'classpathFile', 'classpathManifestFile', 'baseRuntimeDescriptorFile',
                'overlaySourceFile', 'overlayPatchFile', 'validationFile'}
    check(required <= inputs.keys() and descriptor.get('diagnosticOnly') is False,
          'Timing runtime lacks the required source, patch, validation, or nondiagnostic identity')
    check(inputs['baseRuntimeDescriptorFile'] == COMMON_FILE and identity.sha(COMMON_FILE) == COMMON_SHA,
          'Timing runtime does not use the preserved common128 harness')
    base = json.loads(COMMON_FILE.read_text())
    base_inputs = descriptor_inputs(base)
    base_cp = base_inputs['classpathFile'].read_text().strip()
    base_manifest = identity.classpath_manifest(base_cp)
    _, original = identity.original_identity()
    check(len(base_manifest) == 128 and base_manifest[1:] == original
          and base_manifest == json.loads(base_inputs['classpathManifestFile'].read_text())
          and base_manifest[0]['sha256'] == COMMON_PREFIX_SHA
          and base_manifest[0]['files'] == 15 and base['diagnosticOnly'] is False,
          'Preserved common128 runtime changed')
    cp = inputs['classpathFile'].read_text().strip()
    manifest = identity.classpath_manifest(cp)
    check(len(manifest) == 129 and manifest[1:] == base_manifest
          and manifest == json.loads(inputs['classpathManifestFile'].read_text()),
          'Experimental prefix must be the only addition to the exact common128 runtime')
    check(manifest[0]['kind'] == 'tree', 'Experimental materializer prefix must be a directory')
    overlay_files = identity.tree_files(manifest[0]['path'])
    stem = 'org/eclipse/rdf4j/sail/lmdb/evaluation/NativeResultMaterializer'
    check(overlay_files and all(n.startswith(stem) and n.endswith('.class') for n in overlay_files),
          'Unrelated or diagnostic classes in timing overlay')
    check('sourceIdentity' in descriptor and isinstance(descriptor['sourceIdentity'], str)
          and descriptor['sourceIdentity'], 'Runtime source identity missing')
    return {'descriptor': descriptor, 'inputs': inputs, 'classpath': cp, 'manifest': manifest,
            'baseInputs': base_inputs, 'baseDescriptor': base, 'overlayClassFiles': overlay_files}


