def validate_protocol(path):
    protocol = json.loads(path.read_text())
    validate_design(protocol)
    check(protocol['status'] == 'frozen-ready', 'Protocol not frozen')
    verified_file(__file__, protocol['driverFileSha256'])
    verified_file(HERE / 'runtime_identity.py', protocol['identityHelperFileSha256'])
    runtime_path = verified_file(protocol['runtimeDescriptorFile'], protocol['runtimeDescriptorFileSha256'])
    selection_path = verified_file(protocol['selectionFile'], protocol['selectionFileSha256'])
    check(protocol['runtime'] == json.loads(runtime_path.read_text()), 'Runtime descriptor differs from freeze')
    selection = validated_selection(selection_path)
    check(selection == protocol['selection'], 'Target selection differs from freeze')
    runtime = validate_runtime(runtime_path)
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        check(not os.environ.get(key), 'Unprescribed JVM environment: ' + key)
    return protocol, runtime


def arm_properties(protocol, fixture_name, arm):
    definition = ARM_DEFINITIONS[arm]
    omit = ','.join(protocol['selection']['fixtureMasks'][fixture_name]) if arm == 'dense-omit' else ''
    return {TRANSPORT_PROPERTY: definition['transportMode'], OMIT_PROPERTY: omit}


def route_histogram(samples):
    histogram = Counter()
    for sample in samples:
        counters = sample['counters']
        signature = {'selections': sample['successfulSelections'],
            **{k: counters[k] for k in ('compiledBinds', 'interpretedBinds', 'aggregateCompiledBinds',
                                       'aggregateInterpretedBinds', 'semanticNativeCompiles')}}
        histogram[json.dumps(signature, sort_keys=True, separators=(',', ':'))] += 1
    return [{'signature': json.loads(k), 'count': v} for k, v in sorted(histogram.items())]


def normalized_metadata(metadata):
    result = dict(metadata)
    for key in ('arm', 'source', 'store'):
        result.pop(key, None)
    result['jvmArguments'] = [x for x in result['jvmArguments']
        if not any(x.startswith('-D' + p + '=') for p in (TRANSPORT_PROPERTY, OMIT_PROPERTY))]
    result['systemProperties'] = {k: v for k, v in result['systemProperties'].items()
        if k not in (TRANSPORT_PROPERTY, OMIT_PROPERTY)}
    return result


def validate_run(folder, fixture_name, arm, runtime, protocol):
    fixture = FIXTURES[fixture_name]
    expected_rows, expected_checksum = fixture['metadata']['expectedRows'], fixture['metadata']['expectedChecksum']
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines() if line.strip()]
    check(len(records) == 14 and records[0].get('type') == 'metadata', 'Expected metadata plus thirteen queries')
    metadata, samples = records[0], records[1:]
    check([s['iteration'] for s in samples] == list(range(-8, 5))
          and [s['stage'] for s in samples] == ['warmup'] * 8 + ['measurement'] * 5, 'Unexpected query chronology')
    check(metadata['arm'] == arm and metadata['source'] == runtime['descriptor']['sourceIdentity'],
          'Source/arm identity mismatch')
    expected = {**fixture['metadata'], **CONFIGURATION, 'consumption': 'full',
        'maxHeapBytes': 1073741824, 'warmup': 8, 'measurementsToRun': 5, 'javaVersion': '25.0.5+8-LTS',
        'namespaceExperimentHarness': 'native-and-direct-adjacency-v1',
        'projectedNames': fixture['projectedNames']}
    check(all(metadata.get(k) == v for k, v in expected.items()), 'Fixture/JVM/configuration differs')
    properties = arm_properties(protocol, fixture_name, arm)
    check(metadata['jvmArguments'] == JVM + ['-D' + k + '=' + v for k, v in properties.items()]
          and metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
                                              BUDGET_PROPERTY: '536870912', **properties},
          'Unexpected JVM arguments, properties, or instrumentation')
    setup = metadata['adjacencySetup']
    check(setup['state'] == 'ACTIVE' and setup['currentRevisionReady']
          and setup['appliedRevision'] == setup['currentDataRevision'], 'Adjacency not ready before queries')
    reasons = []
    for sample in samples:
        check(sample['type'] == 'sample' and sample['arm'] == arm and sample['valid'] and sample['complete']
              and sample['rows'] == expected_rows and sample['checksum'] == expected_checksum
              and sample['rowCountValid'] and sample['checksumValid'] and sample['partialMembershipValid']
              and sample['bindingReads'] == expected_rows * fixture['metadata']['width']
              and sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0
              and sample['ledgerReleased'] and all(sample[k] >= 0 for k in METRICS),
              'Invalid result, allocation, timing, binding reads, or unreleased ledger')
        if fixture_name == 'shared-tail':
            check(sample['exactBagValid'], 'Shared-tail independent exact bag oracle failed')
        counters, adjacency = sample['counters'], sample['adjacency']
        check(counters['semanticNativeCompiles'] == 1 and counters['lazyValueCalls'] >= 0,
              'Expected one native compile and a valid resolver count per query')
        check(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
              and adjacency['appliedRevisionBefore'] == adjacency['currentRevisionBefore']
              == adjacency['appliedRevisionAfter'] == adjacency['currentRevisionAfter']
              == setup['currentDataRevision'], 'Adjacency revision/readiness changed')
        admissions = counters['coordinateAdmissions']
        check(admissions and admissions['opened'] == (0 if arm == 'off' else 1)
              and admissions['initialAdmissionRefused'] == admissions['growthAdmissionRefused'] == 0,
              'Coordinate-owner admission differs from the prescribed arm')
        if not (sample['autoRequested'] and sample['auto'] and sample['successfulSelections']
                and not any('forced' in item['mode'] for item in sample['successfulSelections'])
                and counters['irOpened'] == 1 and counters['irRows'] == expected_rows
                and adjacency['lookupHits'] > 0):
            reasons.append('iteration %s: normal AUTO/native/adjacency target not observed' % sample['iteration'])
        if sample['stage'] == 'measurement' and not (counters['compiledBinds'] == 1
                and counters['interpretedBinds'] == counters['aggregateCompiledBinds']
                == counters['aggregateInterpretedBinds'] == 0):
            reasons.append('iteration %s: compiled-only measured IR not observed' % sample['iteration'])
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    check(audit['format'] == 1 and audit['type'] == 'root-host-audit'
          and audit['readPhase'] == fixture['rootReadPhase'] and audit['harnessMain'] == fixture['harnessMain']
          and audit['harnessReturned'] and audit['harnessFailureClass'] is None
          and audit['semanticNativeCompilesTotal'] == sum(s['counters']['semanticNativeCompiles'] for s in samples) == 13,
          'Post-main root audit schema or compile reconciliation failed')
    if audit['hostedGenericTotal'] != 0:
        reasons.append('Generic outer root observed')
    validation = {'resultValidity': 'passed', 'targetQualified': not reasons, 'targetQualificationReasons': reasons,
        'fixture': fixture_name, 'queryCount': len(samples), 'measuredQueryCount': 5, 'oracle': fixture['oracle'],
        'factorAdmissionObservation': 'Uninstrumented queries report coordinate-owner admission. Factor-page admission refusal is separately established by pinned diagnostics.',
        'adjacencyInterpretation': 'Positive lookupHits establish query-time adjacency use, not exclusive use or use on every result row.'}
    identity.write_new(folder / 'validation.json', validation)
    return metadata, samples, audit, samples[8:], validation


def run_fork(command, folder, timeout):
    started = time.time_ns()
    identity.write_new(folder / 'command.json', {'argv': command, 'cwd': str(ROOT), 'startedEpochNs': started})
    process, failure = None, None
    try:
        with (folder / 'console.log').open('xb') as console:
            process = subprocess.Popen(command, cwd=ROOT, stdout=console, stderr=subprocess.STDOUT,
                                       start_new_session=True)
            deadline = time.monotonic() + timeout
            next_report = time.monotonic() + 30
            while process.poll() is None:
                if time.monotonic() >= deadline:
                    raise TimeoutError('Prespecified fork deadline exceeded')
                if time.monotonic() >= next_report:
                    print('  JVM still running; raw output preserved', flush=True)
                    next_report += 30
                time.sleep(.2)
            check(process.wait() == 0, 'JVM exited unsuccessfully')
    except BaseException as problem:
        failure = {'exception': type(problem).__name__, 'message': str(problem)}
        raise
    finally:
        if process is not None and process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
        identity.write_new(folder / 'process-result.json', {'exitCode': process.returncode if process else None,
            'startedEpochNs': started, 'finishedEpochNs': time.time_ns(), 'failure': failure})


def dense_pair_audit(a, b):
    check(a['fixture'] == b['fixture'] and a['round'] == b['round'], 'Dense audit pairing mismatch')
    comparisons = []
    for left, right in zip(a['samples'], b['samples'], strict=True):
        check(left['iteration'] == right['iteration'] and left['stage'] == right['stage'],
              'Dense chronology differs')
        comparisons.append({'iteration': left['iteration'], 'stage': left['stage'],
            'allResolverCalls': left['counters']['lazyValueCalls'],
            'omitResolverCalls': right['counters']['lazyValueCalls'],
            'resolverCallsEqual': left['counters']['lazyValueCalls'] == right['counters']['lazyValueCalls'],
            'routeAndTierEqual': route_histogram([left]) == route_histogram([right]),
            'adjacencyLookupHitsEqual': left['adjacency']['lookupHits'] == right['adjacency']['lookupHits']})
    return {'fixture': a['fixture'], 'round': a['round'], 'queries': comparisons,
        'passed': all(v['resolverCallsEqual'] and v['routeAndTierEqual']
                      and v['adjacencyLookupHitsEqual'] for v in comparisons)}


def summary(runs, complete, errors, pair_audits):
    result = {'complete': complete, 'errors': errors, 'completedJvms': len(runs),
        'rawQueryCount': sum(len(r['samples']) for r in runs),
        'rawMeasuredQueryCount': sum(sum(s['stage'] == 'measurement' for s in r['samples']) for r in runs),
        'comparisonStatus': 'complete prespecified dual-fixture protocol' if complete else 'incomplete; no accepted comparison estimates',
        'ratioDefinition': 'Ratio of fresh-JVM medians of all five measurements within the same round and fixture; no cross-fixture pooling.',
        'mechanismEvidence': {'evaluated': False, 'prospectiveScreen': MECHANISM_SCREEN},
        'densePairAudits': pair_audits, 'comparisons': []}
    if not complete:
        return result
    indexed = {(r['fixture'], r['round'], r['arm']): r for r in runs}
    by_pair = {}
    for fixture_name in FIXTURE_ORDER:
        for candidate, comparator in PAIRS:
            pairs = []
            for round_index in range(6):
                a, b = indexed[fixture_name, round_index, candidate], indexed[fixture_name, round_index, comparator]
                pairs.append({'round': round_index,
                    'ratios': {k: a['medians'][k] / b['medians'][k] if b['medians'][k] else None for k in METRICS},
                    'routeTierHistogramsEqual': a['routeTierHistogram'] == b['routeTierHistogram']})
            values = {k: [p['ratios'][k] for p in pairs if p['ratios'][k] is not None] for k in METRICS}
            entry = {'fixture': fixture_name, 'candidate': candidate, 'comparator': comparator, 'pairs': pairs,
                'medianRatios': {k: statistics.median(v) if v else None for k, v in values.items()},
                'ratioRanges': {k: [min(v), max(v)] if v else None for k, v in values.items()},
                'allSixLatencyRatiosFavorCandidate': all(p['ratios']['totalNs'] < 1 for p in pairs),
                'allRouteTierHistogramsEqual': all(p['routeTierHistogramsEqual'] for p in pairs)}
            result['comparisons'].append(entry)
            by_pair[fixture_name, candidate, comparator] = entry
    gates = [{'name': 'all 156 matched dense query pairs preserve resolver counts, route/tier, and adjacency hits',
              'passed': len(pair_audits) == 12 and all(a['passed'] for a in pair_audits)}]
    for fixture_name in FIXTURE_ORDER:
        entry = by_pair[fixture_name, 'dense-omit', 'dense-all']
        latencies = [p['ratios']['totalNs'] for p in entry['pairs']]
        allocations = [p['ratios']['allThreadAllocatedBytes'] for p in entry['pairs']]
        gates += [
            {'name': fixture_name + ' median paired total latency <=0.95',
             'passed': statistics.median(latencies) <= 0.95, 'medianRatio': statistics.median(latencies)},
            {'name': fixture_name + ' all six latency ratios <1.0',
             'passed': all(v < 1.0 for v in latencies), 'ratios': latencies},
            {'name': fixture_name + ' median allocation ratio <=1.0',
             'passed': statistics.median(allocations) <= 1.0, 'medianRatio': statistics.median(allocations)},
            {'name': fixture_name + ' every allocation ratio <=1.02',
             'passed': max(allocations) <= 1.02, 'ratios': allocations}]
    result['mechanismEvidence'] = {'evaluated': True, 'prospectiveScreen': MECHANISM_SCREEN, 'gates': gates,
        'passed': all(g['passed'] for g in gates),
        'interpretation': 'Mechanism evidence only. A fixture-specific name mask is not promoted to production even if every gate passes.'}
    return result


def execute(args):
    protocol_path = args.protocol.resolve(strict=True)
    protocol_sha = identity.sha(protocol_path)
    protocol, runtime = validate_protocol(protocol_path)
    if args.validate_only:
        print('Frozen publication protocol/runtime validation passed; no JVM launched.')
        return
    check(args.slot_released and args.output is not None, 'Execution requires an exclusive slot and new output path')
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    (output / 'used-protocol.json').write_bytes(protocol_path.read_bytes())
    watched = {str(protocol_path): protocol_sha, str(Path(__file__).resolve()): protocol['driverFileSha256'],
               protocol['identityHelperFile']: protocol['identityHelperFileSha256'],
               protocol['runtimeDescriptorFile']: protocol['runtimeDescriptorFileSha256'],
               protocol['selectionFile']: protocol['selectionFileSha256'], str(COMMON_FILE): COMMON_SHA}
    for entry in protocol['selection']['diagnosticEvidenceFiles']:
        watched[entry['path']] = entry['sha256']
    consumed = output / 'runtime-identity'
    consumed.mkdir()
    identity.write_new(consumed / 'runtime-descriptor.json', runtime['descriptor'])
    for group in ('inputs', 'baseInputs'):
        for key, path in runtime[group].items():
            watched[str(path)] = identity.sha(path)
            (consumed / (group + '-' + key + '-' + path.name)).write_bytes(path.read_bytes())
    identity.write_new(output / 'preflight.json', {'protocolSha256': protocol_sha,
        'runtimeManifest': runtime['manifest'], 'watchedFiles': watched,
        'overlayClassFiles': runtime['overlayClassFiles']})
    runs, errors, metadata_references, route_references, pair_audits = [], [], {}, {}, []
    last_process_end = 0
    for round_index, order in enumerate(protocol['balancedOrders']):
        if errors:
            break
        for fixture_position, fixture_name in enumerate(protocol['fixtureOrdersByRound'][round_index]):
            if errors:
                break
            fixture = FIXTURES[fixture_name]
            for position, arm in enumerate(order):
                folder = output / f'round-{round_index:02d}-{fixture_position:02d}-{fixture_name}-{position:02d}-{arm}'
                folder.mkdir()
                properties = arm_properties(protocol, fixture_name, arm)
                command = [JAVA, *JVM, *['-D' + k + '=' + v for k, v in properties.items()],
                    '-cp', runtime['classpath'], fixture['launcher'], '--arm=' + arm,
                    '--source=' + runtime['descriptor']['sourceIdentity'], '--warmup=8', '--iterations=5',
                    *fixture['arguments'], '--consumption=full', '--output=' + str(folder / 'samples.jsonl'),
                    '--store=' + str(folder / 'store')]
                print(f'Running round {round_index + 1}/6, {fixture_name}, position {position + 1}/3: {arm}', flush=True)
                try:
                    verified_file(protocol_path, protocol_sha)
                    verified_file(__file__, protocol['driverFileSha256'])
                    verified_file(HERE / 'runtime_identity.py', protocol['identityHelperFileSha256'])
                    # Only the small experimental prefix is hashed between forks. The full
                    # immutable runtime was checked before the loop and is checked after it.
                    check(identity.tree_files(runtime['manifest'][0]['path']) == runtime['overlayClassFiles'],
                          'Timing materializer prefix changed before fork')
                    run_fork(command, folder, protocol['timeoutSeconds'])
                    process = json.loads((folder / 'process-result.json').read_text())
                    check(process['startedEpochNs'] >= last_process_end, 'Timed JVM intervals overlap')
                    last_process_end = process['finishedEpochNs']
                    metadata, samples, audit, measured, validation = validate_run(folder, fixture_name, arm, runtime, protocol)
                    normalized = normalized_metadata(metadata)
                    if fixture_name not in metadata_references:
                        metadata_references[fixture_name] = normalized
                    check(normalized == metadata_references[fixture_name], 'Normalized input/JVM metadata differs within fixture')
                    measured_routes = route_histogram(measured)
                    if fixture_name not in route_references:
                        route_references[fixture_name] = measured_routes
                    same_route = measured_routes == route_references[fixture_name]
                    runs.append({'round': round_index, 'fixture': fixture_name, 'fixturePosition': fixture_position,
                        'position': position, 'arm': arm, 'transportMode': properties[TRANSPORT_PROPERTY],
                        'omitFactorTargets': properties[OMIT_PROPERTY], 'directory': str(folder), 'metadata': metadata,
                        'samples': samples, 'rootAudit': audit, 'validation': validation,
                        'medians': {k: statistics.median(s[k] for s in measured) for k in METRICS},
                        'counterMedians': {k: statistics.median(s['counters'][k] for s in measured)
                            for k, v in measured[0]['counters'].items() if isinstance(v, (int, float))},
                        'adjacencyLookupHits': [s['adjacency']['lookupHits'] for s in measured],
                        'routeTierHistogram': measured_routes, 'routeTierHistogramMatchesFirstFixtureFork': same_route,
                        'processInterval': process})
                    check(validation['targetQualified'], '; '.join(validation['targetQualificationReasons']))
                    check(same_route, 'Measured AUTO route/tier histogram changed within this fixture')
                    dense = {r['arm']: r for r in runs if r['fixture'] == fixture_name
                             and r['round'] == round_index and r['arm'] != 'off'}
                    if arm != 'off' and len(dense) == 2:
                        pair_audit = dense_pair_audit(dense['dense-all'], dense['dense-omit'])
                        pair_audits.append(pair_audit)
                        check(pair_audit['passed'], 'Dense publication arms changed resolver calls or per-query routes')
                    print(f'  completed {len(runs)}/36; all 13 queries valid, target qualified', flush=True)
                except Exception as error:
                    errors.append({'round': round_index, 'fixture': fixture_name, 'position': position, 'arm': arm,
                        'directory': str(folder), 'exception': type(error).__name__, 'message': str(error),
                        'policy': 'Preserve raw records and stop; no replacement, exclusions, extra rounds, or forced routes'})
                    print('  BLOCKED: ' + str(error), flush=True)
                (output / 'runs.json').write_text(json.dumps(runs, indent=2) + '\n')
                (output / 'summary.json').write_text(json.dumps(summary(runs, False, errors, pair_audits), indent=2) + '\n')
                if errors:
                    break
    post = {'identityFilesUnchanged': all(Path(p).is_file() and identity.sha(p) == h for p, h in watched.items()),
            'runtimeIdentityUnchanged': identity.classpath_manifest(runtime['classpath']) == runtime['manifest']}
    identity.write_new(output / 'post-run-preservation.json', post)
    if not post['identityFilesUnchanged'] or not post['runtimeIdentityUnchanged']:
        errors.append({'exception': 'IdentityMismatch', 'message': 'Runtime/protocol/driver/source evidence changed'})
    complete = len(runs) == 36 and len(pair_audits) == 12 and not errors
    (output / 'summary.json').write_text(json.dumps(summary(runs, complete, errors, pair_audits), indent=2) + '\n')
    print(json.dumps({'output': str(output), 'complete': complete, 'completedJvms': len(runs), 'errors': errors}))
    if not complete:
        raise SystemExit(1)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--protocol', type=Path, required=True)
    parser.add_argument('--freeze', action='store_true')
    parser.add_argument('--runtime', type=Path)
    parser.add_argument('--selection', type=Path)
    parser.add_argument('--output', type=Path)
    parser.add_argument('--validate-only', action='store_true')
    parser.add_argument('--slot-released', action='store_true')
    args = parser.parse_args()
    if args.freeze:
        freeze(args)
    else:
        check(args.runtime is None and args.selection is None, 'Runtime and selection are read from the frozen protocol')
        execute(args)


if __name__ == '__main__':
    main()
